package spireledger;
import com.google.gson.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** UI-only fixtures, never human demonstrations. No original saves are read or changed. */
public final class HistoryIndexCheck {
    static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
    static JsonObject run(int i,long now){
        JsonObject run=new JsonObject();run.addProperty("schema",Recorder.SCHEMA);JsonObject m=new JsonObject();m.addProperty("run_id","history-ui-fixture-"+i);m.addProperty("seed","1234567890123456789");m.addProperty("dataset_origin","test_fixture");run.add("metadata",m);JsonArray records=new JsonArray();run.add("records",records);
        JsonObject state=new JsonObject();state.addProperty("class",new String[]{"IRONCLAD","THE_SILENT","DEFECT","WATCHER"}[i%4]);state.addProperty("ascension",i%21);state.addProperty("floor",40+i%10);state.addProperty("hp",67);state.addProperty("max_hp",80);state.addProperty("gold",99);JsonArray deck=new JsonArray();JsonObject card=new JsonObject();card.addProperty("id","Bash");card.addProperty("upgrades",1);card.addProperty("misc",i);deck.add(card);state.add("deck",deck);JsonArray relics=new JsonArray();JsonObject relic=new JsonObject();relic.addProperty("id","Burning Blood");relic.addProperty("counter",-1);relics.add(relic);state.add("relics",relics);
        JsonObject d=Recorder.object("decision");d.addProperty("decision_id","d-"+i);d.addProperty("branch_id","a");d.addProperty("time_ms",now-(i%40)*86400000L);d.addProperty("source","COMBAT_REWARD");d.addProperty("action_source","unknown");d.addProperty("candidate_id",i%3==0?"card:0":i%3==1?"skip":"bowl");d.add("before",state);JsonArray candidates=new JsonArray();for(String type:new String[]{"card","skip","bowl"}){JsonObject c=Recorder.object(type);c.addProperty("candidate_id",type.equals("card")?"card:0":type);if(type.equals("card"))c.add("card",card);candidates.add(c);}d.add("candidates",candidates);records.add(d);
        if(i%5!=0){JsonObject result=Recorder.object("result");result.addProperty("decision_id","d-"+i);result.addProperty("status","confirmed");result.addProperty("branch_id",i%2==0?"b":"a");result.addProperty("time_ms",now-(i%40)*86400000L);result.add("after",state);records.add(result);}
        if(i%4!=0){JsonObject end=Recorder.object("ending");end.addProperty("outcome",i%4==1?"victory":i%4==2?"death":"unknown");end.addProperty("branch_id","a");end.addProperty("time_ms",now-(i%40)*86400000L);end.add("state",state);records.add(end);}return run;
    }
    public static void main(String[] args)throws Exception{
        if(args[0].equals("--summary")){HistoryIndex.Summary s=HistoryIndex.readSummary(Paths.get(args[1]));JsonObject o=new JsonObject();o.addProperty("run_id",s.id);o.addProperty("picks",s.picks);o.addProperty("skips",s.skips);o.addProperty("bowls",s.bowls);o.addProperty("pending",s.pending);o.addProperty("outcome",s.outcome);o.addProperty("branches",s.branches.size());System.out.println(o);return;}
        Path root=Paths.get(args[0]);Files.createDirectories(root);long now=System.currentTimeMillis();List<Path> files=new ArrayList<>();Map<Path,byte[]> before=new HashMap<>();
        for(int i=0;i<1200;i++){Path file=root.resolve("fixture-"+i).resolve("run.json");Files.createDirectories(file.getParent());byte[] bytes=run(i,now).toString().getBytes(StandardCharsets.UTF_8);Files.write(file,bytes);files.add(file);before.put(file,bytes);}
        Path duplicate=root.resolve("duplicate/run.json");Files.createDirectories(duplicate.getParent());Files.write(duplicate,before.get(files.get(1)));Path broken=root.resolve("corrupt/run.json");Files.createDirectories(broken.getParent());Files.write(broken,"<broken>".getBytes(StandardCharsets.UTF_8));
        long start=System.nanoTime();HistoryIndex.Index index=HistoryIndex.scan(root,null);long scan=(System.nanoTime()-start)/1000000;
        check(index.runs.size()==1200,"same run counted once");check(index.duplicates==1&&index.errors.size()==1,"duplicate and corrupt reports");
        check(HistoryIndex.filter(index.runs,"IRONCLAD",-1,"",0,"",false,now).size()==300,"class");check(HistoryIndex.filter(index.runs,"",20,"",0,"",false,now).size()>0,"ascension 20");check(HistoryIndex.filter(index.runs,"",-1,"victory",0,"",false,now).size()==300,"victory");check(HistoryIndex.filter(index.runs,"",-1,"incomplete",0,"",false,now).size()==300,"unknown ending not death");check(HistoryIndex.filter(index.runs,"",-1,"",7,"",false,now).size()==240,"date inclusive boundary");check(HistoryIndex.filter(index.runs,"",-1,"",30,"",false,now).size()==930,"30 days");for(HistoryIndex.Summary s:index.runs)s.localizedSearch="痛击";check(HistoryIndex.filter(index.runs,"",-1,"",0,"痛击",false,now).size()==1200,"UTF8 localized search");check(HistoryIndex.filter(index.runs,"",-1,"",0,"1234567890123456789",false,now).size()==1200,"64-bit seed string");check(HistoryIndex.filter(index.runs,"",-1,"",0,"Burning Blood",false,now).size()==1200,"relic ID");check(HistoryIndex.filter(index.runs,"",-1,"",0,"",true,now).size()==480,"SL branches not separate runs");check(HistoryIndex.filter(index.runs,"",-1,"",0,"不存在",false,now).isEmpty(),"no matches");
        check(HistoryIndex.filter(index.runs,"",-1,"interrupted",0,"",false,now).size()==300,"unfinished history is interrupted");
        JsonObject abandoned=run(0,now);JsonObject ending=Recorder.object("ending");ending.addProperty("outcome","abandon");ending.addProperty("branch_id","a");abandoned.getAsJsonArray("records").add(ending);check(HistoryIndex.summarize(abandoned,true).outcome.equals("abandon"),"abandon ending retained while live");check(HistoryIndex.summarize(abandoned,false).saveSlot==null,"missing slot stays missing");abandoned.getAsJsonObject("metadata").addProperty("save_slot",2);check(HistoryIndex.summarize(abandoned,false).saveSlot==2,"metadata slot retained");
        HistoryIndex.Summary live=HistoryIndex.summarize(run(0,now),true);check(live.outcome.equals("current"),"live incomplete is current");check(HistoryIndex.summarize(run(3,now),true).outcome.equals("incomplete"),"unknown ending live not in progress");check(live.picks==0&&live.pending==1,"pending not counted");
        JsonObject slAfterDeath=run(2,now);JsonObject load=Recorder.object("load");load.addProperty("branch_id","new-attempt");slAfterDeath.getAsJsonArray("records").add(load);check(HistoryIndex.summarize(slAfterDeath,true).outcome.equals("current"),"SL after old branch death is current");check(HistoryIndex.summarize(slAfterDeath,false).outcome.equals("interrupted"),"SL missing latest ending is interrupted");
        JsonObject conflict=run(1,now);JsonObject contradictory=Recorder.copy(conflict.getAsJsonArray("records").get(1).getAsJsonObject());contradictory.addProperty("status","interrupted");conflict.getAsJsonArray("records").add(contradictory);check(HistoryIndex.summarize(conflict,false).skips==0,"conflicting result not complete");
        start=System.nanoTime();for(int i=0;i<100;i++)HistoryIndex.filter(index.runs,"IRONCLAD",-1,"",30,"Bash",false,now);long filtering=(System.nanoTime()-start)/1000000;
        for(Path p:files)check(Arrays.equals(before.get(p),Files.readAllBytes(p)),"read only");
        // State Notes 0.4.0 records keep their old schema name and directory; both are read, unknown schemas are not.
        Path legacy=root.resolveSibling(root.getFileName()+"-legacy");JsonObject old=run(7,now);old.addProperty("schema","sts1-state-v1");old.getAsJsonObject("metadata").addProperty("run_id","legacy-run");
        Path oldFile=legacy.resolve("legacy-run/run.json");Files.createDirectories(oldFile.getParent());Files.write(oldFile,old.toString().getBytes(StandardCharsets.UTF_8));
        JsonObject alien=run(8,now);alien.addProperty("schema","other-v9");alien.getAsJsonObject("metadata").addProperty("run_id","alien-run");Path alienFile=legacy.resolve("alien-run/run.json");Files.createDirectories(alienFile.getParent());Files.write(alienFile,alien.toString().getBytes(StandardCharsets.UTF_8));
        HistoryIndex.Index both=HistoryIndex.scan(Arrays.asList(root,legacy),null);boolean sawLegacy=false,sawAlien=false;for(HistoryIndex.Summary x:both.runs){sawLegacy|=x.id.equals("legacy-run");sawAlien|=x.id.equals("alien-run");}
        check(sawLegacy&&!sawAlien&&both.runs.size()==index.runs.size()+1,"legacy schema and directory");
        // Abnormal exit: a missing or damaged run.json must not hide the run; it is rebuilt from the journal, run.json.tmp or segments, read-only.
        Path rec=root.resolveSibling(root.getFileName()+"-recovered");String journalId="00000000-0000-0000-0000-00000000000a",tmpId="00000000-0000-0000-0000-00000000000b",segId="00000000-0000-0000-0000-00000000000c";
        JsonObject j=run(20,now);j.getAsJsonObject("metadata").addProperty("run_id",journalId);JsonObject header=new JsonObject();header.add("header",j.get("metadata"));Files.createDirectories(rec.resolve(journalId));Files.write(rec.resolve(journalId+"/events.jsonl"),(header+"\n"+j.getAsJsonArray("records").get(0)+"\n{\"type\":\"res").getBytes(StandardCharsets.UTF_8));
        JsonObject t=run(1,now);t.getAsJsonObject("metadata").addProperty("run_id",tmpId);Files.createDirectories(rec.resolve(tmpId));Files.write(rec.resolve(tmpId+"/run.json.tmp"),t.toString().getBytes(StandardCharsets.UTF_8));
        JsonObject g=run(2,now);g.getAsJsonObject("metadata").addProperty("run_id",segId);Files.createDirectories(rec.resolve(segId));Files.write(rec.resolve(segId+"/run.json"),"<broken".getBytes(StandardCharsets.UTF_8));JsonArray all=g.getAsJsonArray("records");for(int part=0;part<2;part++){JsonObject seg=Recorder.copy(g);JsonArray slice=new JsonArray();for(int k=part==0?0:1;k<(part==0?1:all.size());k++)slice.add(all.get(k));seg.add("records",slice);Files.write(rec.resolve(segId+"/segment-0000"+(part+1)+".json"),seg.toString().getBytes(StandardCharsets.UTF_8));}
        Map<Path,byte[]> recBefore=new HashMap<>();try(java.util.stream.Stream<Path> w=Files.walk(rec)){for(Path p:(Iterable<Path>)w.filter(Files::isRegularFile)::iterator)recBefore.put(p,Files.readAllBytes(p));}
        HistoryIndex.Index recovered=HistoryIndex.scan(rec,null);Map<String,HistoryIndex.Summary> byId=new HashMap<>();for(HistoryIndex.Summary x:recovered.runs)byId.put(x.id,x);
        check(recovered.errors.isEmpty()&&byId.size()==3,"runs without a usable run.json stay visible: "+byId.keySet()+" "+recovered.errors);
        check(byId.get(journalId).outcome.equals("interrupted")&&byId.get(journalId).pending==1,"journal tail without result stays interrupted and pending");check(byId.get(tmpId).outcome.equals("victory"),"run.json.tmp copy used");check(byId.get(segId).outcome.equals("death")&&byId.get(segId).bowls==1,"segments used when run.json is damaged");
        boolean interrupted=false;for(JsonElement e:HistoryIndex.readDetail(byId.get(journalId).file).getAsJsonArray("records"))interrupted|="interrupted".equals(HistoryIndex.str(e.getAsJsonObject(),"status"));check(interrupted,"unfinished tail marked interrupted in the detail view");
        check(StatsIndex.scan(rec.resolve("no-native"),recovered,null).errors.isEmpty(),"stats read recovered runs");
        try(java.util.stream.Stream<Path> w=Files.walk(rec)){check(w.filter(Files::isRegularFile).count()==recBefore.size(),"recovery creates no files");}for(Map.Entry<Path,byte[]> e:recBefore.entrySet())check(Arrays.equals(e.getValue(),Files.readAllBytes(e.getKey())),"recovery read only");
        HistoryIndex.Summary atStart=HistoryIndex.summarize(run(1,now),false),atEnd=HistoryIndex.summarize(run(2,now),false),otherSlot=HistoryIndex.summarize(run(3,now),false),unknownSlot=HistoryIndex.summarize(run(4,now),false);atStart.saveSlot=atEnd.saveSlot=2;otherSlot.saveSlot=1;atStart.time=unknownSlot.time=otherSlot.time=100;atEnd.time=200;
        List<HistoryIndex.Summary> slots=Arrays.asList(atStart,atEnd,otherSlot,unknownSlot);
        check(HistoryIndex.filter(slots,"",-1,"",0,"",false,now,2,100,200).equals(Collections.singletonList(atStart)),"slot filter separates slots and includes start, excludes end");
        check(HistoryIndex.filter(slots,"",-1,"",0,"",false,now,null,100,200).equals(Collections.singletonList(unknownSlot)),"null slot shows only unknown records");
        check(HistoryIndex.filter(slots,"",-1,"",0,"",false,now,2,101,200).isEmpty(),"time before start excluded");
        check(HistoryIndex.filter(slots,"",-1,"",0,"",false,now,2,0,0).equals(Arrays.asList(atStart,atEnd)),"unbounded dates keep the current slot");
        Path savedRoot=root.resolve("saved-abandon");JsonObject metadata=new JsonObject();metadata.addProperty("save_slot",2);JsonObject ref;String savedId;
        try(Recorder saved=new Recorder(savedRoot,metadata,null)){JsonObject state=new JsonObject();state.addProperty("class","IRONCLAD");ref=saved.checkpoint(state);savedId=saved.runId;}
        Path savedLog=savedRoot.resolve(savedId).resolve("events.jsonl");byte[] original=Files.readAllBytes(savedLog);
        check(!StateMod.abandonSaved(savedRoot,ref,1)&&Arrays.equals(original,Files.readAllBytes(savedLog)),"other slot never changed");
        JsonObject bad=Recorder.copy(ref);bad.addProperty("checkpoint_id","unknown");check(!StateMod.abandonSaved(savedRoot,bad,2)&&Arrays.equals(original,Files.readAllBytes(savedLog)),"unmatched checkpoint never changed");
        check(StateMod.abandonSaved(savedRoot,ref,2),"exact saved checkpoint abandoned");JsonObject ended=HistoryIndex.document(savedRoot.resolve(savedId).resolve("run.json"));check(HistoryIndex.summarize(ended,false).outcome.equals("abandon"),"main menu abandon visible");
        try(Recorder resumed=new Recorder(savedRoot,metadata,savedId)){resumed.resume(ref,new JsonObject());resumed.flush();check(HistoryIndex.summarize(resumed.document(),true).outcome.equals("current"),"continued saved checkpoint returns to same logical run");check(HistoryIndex.summarize(resumed.document(),false).outcome.equals("interrupted"),"closed resumed run is interrupted");}
        System.out.println("HistoryIndexCheck PASS: 1200 UI-only fixture runs, scan_ms="+scan+", 100_filters_ms="+filtering+", read-only, mixed class/outcome/date/SL/pending/conflict/corruption, recovery without run.json");
    }
}
